'use client';
import{useState}from"react";import Nav from"../../components/Nav";import{genToWei,writeContract}from"../../lib/contract";
export default function CreatePage(){const[f,setF]=useState({title:"",requirements:"",provider:"",deadline:"",amount:"1"});const[account,setAccount]=useState("");const[status,setStatus]=useState("");const[loading,setLoading]=useState(false);const u=(k,v)=>setF(x=>({...x,[k]:v}));
async function create(){try{setLoading(true);setStatus("Waiting for wallet…");let a=account;if(!a){if(!window.ethereum)throw new Error("Install MetaMask or another EVM wallet.");a=(await window.ethereum.request({method:"eth_requestAccounts"}))?.[0];setAccount(a||"")}if(!a)throw new Error("Wallet connection failed.");if(!f.provider.trim())throw new Error("Provider address is required.");if(!f.deadline)throw new Error("Deadline is required.");const tx=await writeContract(a,"create_dispute",[f.title.trim(),f.requirements.trim(),f.provider.trim(),new Date(f.deadline).toISOString()],genToWei(f.amount));setStatus(`Agreement created. Transaction: ${String(tx)}`);setF({title:"",requirements:"",provider:"",deadline:"",amount:"1"})}catch(e){setStatus(e?.message||"Creation failed.")}finally{setLoading(false)}}
return <><Nav/><main className="shell"><div className="max-w-3xl"><span className="badge text-cyan-300">CREATE AGREEMENT</span><h1 className="mt-4 text-4xl font-black">Lock a service agreement</h1><p className="mt-3 muted">The provider address is bound on-chain. GenLayer evaluates only the acceptance requirements you specify.</p><div className="card mt-8 p-6 space-y-5">{[["title","Title","e.g. Build an AI landing page"],["provider","Provider wallet","0x…"]].map(([k,l,p])=><label className="block" key={k}><span className="mb-2 block text-sm font-bold">{l}</span><input className="field" value={f[k]} placeholder={p} onChange={e=>u(k,e.target.value)}/></label>)}<label className="block"><span className="mb-2 block text-sm font-bold">Acceptance requirements</span><textarea className="field min-h-40" value={f.requirements} placeholder="Describe exactly what must be delivered." onChange={e=>u("requirements",e.target.value)}/></label><div className="grid md:grid-cols-2 gap-4"><label><span className="mb-2 block text-sm font-bold">GEN escrow</span><input className="field" type="number" min="0" step="0.01" value={f.amount} onChange={e=>u("amount",e.target.value)}/></label><label><span className="mb-2 block text-sm font-bold">Deadline</span><input className="field" type="datetime-local" value={f.deadline} onChange={e=>u("deadline",e.target.value)}/></label></div><button className="btn btn-primary" onClick={create} disabled={loading}>{loading?"Submitting…":"Create & lock GEN"}</button>{status&&<div className="rounded-xl bg-slate-950 p-4 text-sm text-cyan-200 break-words">{status}</div>}</div></div></main></>}